function largestSquareArea(grid: string[][]): number {
  const R = grid.length, C = grid[0].length;
  let best = 0;
  for (let r = 0; r < R; r++) {
    for (let c = 0; c < C; c++) {
      let k = 0;
      grow: while (r + k < R && c + k < C) {
        for (let i = 0; i <= k; i++) {
          if (grid[r + k][c + i] !== "1" || grid[r + i][c + k] !== "1") break grow;
        }
        k++;
      }
      best = Math.max(best, k);
    }
  }
  return best * best;
}

