class Solution:
    def largestSquareArea(self, grid: List[List[str]]) -> int:
        R, C = len(grid), len(grid[0])
        best = 0
        for r in range(R):
            for c in range(C):
                k = 0
                while r + k < R and c + k < C and all(
                    grid[r + k][c + i] == "1" and grid[r + i][c + k] == "1" for i in range(k + 1)
                ):
                    k += 1
                best = max(best, k)
        return best * best

