function largestSquareArea(grid: string[][]): number {
  const C = grid[0].length;
  let prev = new Array(C + 1).fill(0);
  let best = 0;
  for (const row of grid) {
    const cur = new Array(C + 1).fill(0);
    for (let c = 1; c <= C; c++) {
      if (row[c - 1] === "1") {
        cur[c] = 1 + Math.min(prev[c], cur[c - 1], prev[c - 1]);
        best = Math.max(best, cur[c]);
      }
    }
    prev = cur;
  }
  return best * best;
}

